var sink string

func BenchmarkConcat(b *testing.B) {
	parts := []string{"a", "b", "c", "d", "e"}

	b.Run("plus", func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			s := ""
			for _, p := range parts {
				s += p // allocates each iteration
			}
			sink = s // keep the result
		}
	})

	b.Run("builder", func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			var sb strings.Builder
			for _, p := range parts {
				sb.WriteString(p)
			}
			sink = sb.String()
		}
	})
}
